"""Create the unified, evidence-backed Try-5A.3 completion report."""
import json,subprocess
from pathlib import Path
from freecad_runtime import python_runtime
ROOT=Path(__file__).resolve().parents[3];HERE=ROOT/'experiments/try5A';OUT=HERE/'results/try5a3_final';OUT.mkdir(parents=True,exist_ok=True)
def read(p):return json.loads(p.read_text())
def dump(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
job=OUT/'k1_attachment_job.json';dump(job,{'root':str(ROOT),'output':str(OUT/'k1_attachment.json')});r=subprocess.run([str(python_runtime()),str(HERE/'scripts/freecad_evaluate_a3_attachment.py'),str(job)],cwd=ROOT,capture_output=True,text=True,timeout=600);print(r.stdout or r.stderr);attachment=read(OUT/'k1_attachment.json')
phase14=read(HERE/'results/try5a3_phase14/phase14_validation.json');rank=read(HERE/'results/try5a3_phase14/interface_candidate_ranking.json');k1=read(HERE/'results/try5a3_full/k1_evaluation.json');repair=read(HERE/'results/try5a3_phase510/phase510_validation.json');physical=read(HERE/'results/try5a3_phase510/physical_evaluation.json')
k0={'source':'frozen Try-5A.2 D0 / Try-5A.1 C1 physical baseline','physical_links':11,'bicr':0.0,'positive_gap_carriers':2,'spurious_virtual_geometry_count':1,'exact_collision_events':130,'sweep_free_pose_rate':0.0}
k1row={'source':'current knowledge-guided A2 physical generation','physical_links':k1['interface_summary']['links'],'logical_connected_joint_rate':k1['interface_summary']['connected_joint_rate'],'strict_bicr':attachment['bicr'],'spurious_virtual_geometry_count':k1['interface_summary']['spurious_virtual_geometry_count'],'exact_collision_events':k1['exact_collision']['exact_true'],'sweep_free_pose_rate':k1['sweep_free_pose_rate']}
selection={'retrieval_coverage':phase14['selection_count']/11,'family_change_rate':phase14['family_change_count']/phase14['selection_count'],'custom_interface_rate':phase14['custom_interface_count']/phase14['selection_count'],'changed_joints':[x['joint_id'] for x in rank if x['family_changed']],'selected_family_distribution':{f:sum(x['K1']['selected_family']==f for x in rank) for f in sorted({x['K1']['selected_family'] for x in rank})}}
objectives={'knowledge_base_and_retrieval':phase14['status']=='PASS','knowledge_reaches_current_cad':all(phase14['dataflow_audit'].values()),'mechanical_meaningfulness_gate':k1['mechanical_meaningfulness']['rate']==1 and k1['mechanical_meaningfulness']['patches']==0,'all_repair_scopes_physically_exercised':all(repair['scope_distribution'][s]>0 for s in repair['scope_distribution']),'repair_dataflow_closed':all(repair['dataflow_audit'].values()),'pilot_repairs_accepted_by_four_gates':all(x['decision']=='ACCEPT' and all(v=='PASS' for v in x['acceptance_gates'].values()) for x in physical['cases']),'gt_leakage_absent':not phase14['leakage_audit']['knowledge_contains_forbidden_exact_assets'],'whole_robot_three_round_loop_not_run':repair['no_whole_robot_iterative_loop']}
report={'experiment':'Try-5A.3','status':'COMPLETE_WITH_NEGATIVE_WHOLE_ROBOT_RESULT' if all(objectives.values()) else 'INCOMPLETE','research_result':'The two mechanisms are implemented and physically validated on the frozen pilot cases. Knowledge guidance changes interface choices but does not by itself solve whole-robot physical attachment or collision.','objectives':objectives,'interface_knowledge_metrics':selection,'k0_physical_baseline':k0,'k1_physical_result':k1row,'repair_metrics':{k:repair[k] for k in ('scope_accuracy','scope_distribution','true_replan_rate','repair_success_rate','regression_rate','rollback_rate','meaningful_geometry_rate','meaningless_patch_count','freecad_execution_success_rate')},'interpretation':{'rq1':'PARTIAL: retrieval is stable and changes four selections, but strict BICR remains 0 and exact collision events increase from 130 to 181.','rq2':'SUPPORTED ON PILOTS: R0-R4 scope accuracy and physical repair success are 100%.','rq3':'SUPPORTED ON PILOTS: MGR is 100% and meaningless patch count is 0.','whole_robot_acceptance':'FAIL: current K1 assembly uses separate interface/body final solids and has 0% sweep-free poses.'}}
dump(OUT/'summary.json',report);md=f'''# Try-5A.3 final report\n\nStatus: **{report['status']}**\n\nThe requested mechanism experiment is complete. This is a valid negative whole-robot result, not a claim that the robot is mechanically acceptable.\n\n- Knowledge retrieval coverage: {selection['retrieval_coverage']:.0%}; family change rate: {selection['family_change_rate']:.1%}; CUSTOM rate: {selection['custom_interface_rate']:.0%}.\n- K0 -> K1 strict BICR: {k0['bicr']:.0%} -> {k1row['strict_bicr']:.0%}.\n- K0 -> K1 exact collision events: {k0['exact_collision_events']} -> {k1row['exact_collision_events']}.\n- K0 -> K1 spurious virtual geometry: {k0['spurious_virtual_geometry_count']} -> {k1row['spurious_virtual_geometry_count']}.\n- Scope accuracy: {repair['scope_accuracy']:.0%}; physical repair success: {repair['repair_success_rate']:.0%}; MGR: {repair['meaningful_geometry_rate']:.0%}.\n\nR0, R1, R2, R3 and R4 each have a real baseline/candidate FreeCAD B-Rep pair and passed Mechanical Meaningfulness, Interface/Attachment, Collision and Coarse Morphology acceptance gates. No whole-robot three-round repair loop was run, as required by A.3.\n\nConclusion: the knowledge base and scope arbiter are functional, but knowledge-guided family selection alone does not make the current whole robot acceptable. The next experiment must integrate accepted design-level repairs into the coarse reconstruction loop.\n''';(OUT/'report.md').write_text(md);print(json.dumps(report,indent=2));raise SystemExit(report['status']=='INCOMPLETE')
